/**
 * hextet core FFI 的扁平错误。
 *
 * core 的错误枚举（[`ConfigError`] / [`IdentityError`] / [`AddrError`]）是携带结构化字段的
 * 富枚举，直接映射到 UniFFI 会生成一堆带字段的异常类，且嵌套的 `#[source]` 字段（如
 * `io::Error`）本身不可 FFI。因此本片把错误折叠成一个**扁平**枚举：变体名供 Kotlin 匹配
 * 异常类型，`Display` 文本（thiserror 生成）携带完整人类可读细节（哪个 peer、哪个字段）。
 *
 * ADR-0012 决策 3 记录了取舍：放弃结构化错误字段的可编程性，换取简单、稳定、可匹配的
 * 异常面。若后续 Android 侧需要按字段做精细处理，再按 ADR 重新评估。
 */
sealed class FfiException: kotlin.Exception() {
    
    /**
     * 入参非法（base64 解码失败、长度错误、非法公钥点等）。
     */
    class InvalidInput(
        
        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * 文件/路径 I/O 失败。
     */
    class Io(
        
        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * 配置解析/校验失败（含 peer 校验、subnet 碰撞、路由冲突等）。
     */
    class InvalidConfig(
        
        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    
    /**
     * 地址派生失败（退化 interface id、subnet id 碰撞）。
     */
    class AddressDerivation(
        
        val v1: kotlin.String
        ) : FfiException() {
        override val message
            get() = "v1=${ v1 }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.InvalidInput(
                FfiConverterString.read(buf),
                )
            2 -> FfiException.Io(
                FfiConverterString.read(buf),
                )
            3 -> FfiException.InvalidConfig(
                FfiConverterString.read(buf),
                )
            4 -> FfiException.AddressDerivation(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.InvalidInput -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is FfiException.Io -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is FfiException.InvalidConfig -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
            is FfiException.AddressDerivation -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.v1)
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.InvalidInput -> {
                buf.putInt(1)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is FfiException.Io -> {
                buf.putInt(2)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is FfiException.InvalidConfig -> {
                buf.putInt(3)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
            is FfiException.AddressDerivation -> {
                buf.putInt(4)
                FfiConverterString.write(value.v1, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalString: FfiConverterRustBuffer<kotlin.String?> {
    override fun read(buf: ByteBuffer): kotlin.String? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterString.read(buf)
    }

    override fun allocationSize(value: kotlin.String?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterString.allocationSize(value)
        }
    }

    override fun write(value: kotlin.String?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterString.write(value, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceString: FfiConverterRustBuffer<List<kotlin.String>> {
    override fun read(buf: ByteBuffer): List<kotlin.String> {
        val len = buf.getInt()
        return List<kotlin.String>(len) {
            FfiConverterString.read(buf)
        }
    }

    override fun allocationSize(value: List<kotlin.String>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterString.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<kotlin.String>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterString.write(it, buf)
        }
    }
}




/**
 * @suppress
 */
public object FfiConverterSequenceTypePeerSummary: FfiConverterRustBuffer<List<PeerSummary>> {
