        val sizeForItems = value.map { FfiConverterTypePeerSummary.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<PeerSummary>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypePeerSummary.write(it, buf)
        }
    }
}
